#include <initializer_list>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

template <typename T>
class Stack
{
public:
    Stack() = default;
    Stack(std::initializer_list<T> items) : m_items{ items } {}

    void push(const T& value) { m_items.push_back(value); }

    const T& top() const
    {
        if (m_items.empty()) throw std::out_of_range{ "top() on an empty Stack" };
        return m_items.back();
    }

    // TODO: pop, empty, size

private:
    std::vector<T> m_items{};
};

// TODO: template <typename T> class Queue

int main()
{
    Stack<int> numbers{ 1, 2, 3 };
    std::cout << numbers.top() << '\n';

    try
    {
        Stack<std::string> empty{};
        std::cout << empty.top() << '\n';
    }
    catch (const std::out_of_range& e)
    {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
